package cn.yulin.english;
import android.content.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.function.*;import javax.net.ssl.HttpsURLConnection;
public final class CloudStore {
 public interface Progress{void update(long done,long total);}
 private final Context context;private final File dir;private JSONObject manifest;private String loadedBase="";
 public CloudStore(Context context){this.context=context;dir=new File(context.getFilesDir(),"cloud");dir.mkdirs();}
 private String base(){return context.getSharedPreferences("cloud",0).getString("base","");}
 private String filename(JSONObject item)throws Exception{return item.getString("sha256")+"."+item.getString("extension");}
 private void validate(JSONObject m)throws Exception{if(m.getInt("schema")!=1)throw new IOException("目录版本不兼容");JSONArray files=m.getJSONArray("files");if(files.length()>20000)throw new IOException("目录过大");Set<String> ids=new HashSet<>();for(int i=0;i<files.length();i++){JSONObject x=files.getJSONObject(i);String id=x.getString("id"),sha=x.getString("sha256"),ext=x.getString("extension");long bytes=x.getLong("bytes");if(!id.matches("[a-f0-9]{24}")||!ids.add(id)||!sha.matches("[a-f0-9]{64}")||!ext.matches("doc|docx|pdf|mp3|wav|amr|jpg|jpeg|png|rar|zip")||bytes<1||bytes>536870912L||!x.getString("path").equals("files/"+sha+"."+ext))throw new IOException("云端目录中的文件信息不合法");}}
 private synchronized JSONObject current()throws Exception{String b=base();if(b.isEmpty())throw new IOException("尚未设置云端资料地址");if(manifest!=null&&b.equals(loadedBase))return manifest;File f=new File(dir,"manifest.json");if(!f.exists())throw new IOException("请先刷新云端目录");JSONObject saved=new JSONObject(new String(read(new FileInputStream(f),12000000),StandardCharsets.UTF_8));if(!b.equals(saved.getString("base")))throw new IOException("请刷新新地址的目录");JSONObject m=saved.getJSONObject("manifest");validate(m);manifest=m;loadedBase=b;return m;}
 public synchronized JSONObject item(String id)throws Exception{JSONArray a=current().getJSONArray("files");for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new IOException("此文件尚未发布到云端");}
 public File cached(String id)throws Exception{JSONObject x=item(id);File f=new File(dir,filename(x));if(!f.isFile()||f.length()!=x.getLong("bytes"))throw new IOException("请先下载此资料");return f;}
 private static byte[] read(InputStream in,int limit)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[32768];int n;while((n=input.read(buf))!=-1){if(out.size()+n>limit)throw new IOException("文件超过限制");out.write(buf,0,n);}return out.toByteArray();}}
 private HttpsURLConnection connect(String url,Consumer<HttpsURLConnection> active)throws Exception{URL u=new URL(url);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null)throw new IOException("只支持 HTTPS 下载地址");HttpsURLConnection c=(HttpsURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept-Encoding","identity");active.accept(c);return c;}
 public JSONObject handle(String route,JSONObject body,Progress progress,BooleanSupplier cancelled,Consumer<HttpsURLConnection> active)throws Exception{
  if(route.equals("set")){String b=body.optString("base").trim();if(!b.isEmpty()){URI u=new URI(b);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new IOException("请输入不含密码和查询参数的 HTTPS 资料根地址");if(!b.endsWith("/"))b+="/";}synchronized(this){context.getSharedPreferences("cloud",0).edit().putString("base",b).commit();manifest=null;loadedBase="";}return new JSONObject().put("base",b);}
  if(route.equals("status")){JSONObject result=new JSONObject().put("base",base());JSONArray downloaded=new JSONArray();try{JSONArray a=current().getJSONArray("files");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);File f=new File(dir,filename(x));if(f.isFile()&&f.length()==x.getLong("bytes"))downloaded.put(x.getString("id"));}result.put("published",a.length());}catch(Exception e){result.put("published",0);}return result.put("downloaded",downloaded);}
  if(route.equals("sync")){String b=base();if(b.isEmpty())throw new IOException("请先配置云端资料地址");HttpsURLConnection c=connect(b+"manifest.json",active);try{if(c.getResponseCode()!=200)throw new IOException("无法获取云端目录，请检查地址及公开读取权限");JSONObject m=new JSONObject(new String(read(c.getInputStream(),12000000),StandardCharsets.UTF_8));validate(m);if(cancelled.getAsBoolean())throw new IOException("已取消");synchronized(this){if(!base().equals(b))throw new IOException("下载地址已改变，请重新刷新");File tmp=new File(dir,"manifest.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(new JSONObject().put("base",b).put("manifest",m).toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!tmp.renameTo(new File(dir,"manifest.json")))throw new IOException("目录保存失败");manifest=m;loadedBase=b;}return new JSONObject().put("count",m.getJSONArray("files").length());}finally{c.disconnect();}}
  if(!route.equals("download"))throw new IOException("未知云端操作");String b=base();JSONObject x=item(body.getString("id"));File target=new File(dir,filename(x));long expected=x.getLong("bytes");if(target.exists()&&target.length()==expected)return new JSONObject().put("cached",true);File tmp=new File(dir,filename(x)+".part");long offset=tmp.exists()?tmp.length():0;if(offset>=expected){if(!tmp.delete())throw new IOException("无法重置未完成文件");offset=0;}if(dir.getUsableSpace()<expected-offset+20*1024*1024)throw new IOException("设备空间不足，请先释放空间");HttpsURLConnection c=connect(b+x.getString("path"),active);if(offset>0)c.setRequestProperty("Range","bytes="+offset+"-");try{int code=c.getResponseCode();if(code==200)offset=0;else if(code!=206)throw new IOException("下载失败，服务器状态 "+code);if(code==206){String range=c.getHeaderField("Content-Range");if(range==null||!range.matches("bytes "+offset+"-[0-9]+/"+expected))throw new IOException("服务器续传响应不正确");}long done=offset,last=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(tmp,offset>0)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(cancelled.getAsBoolean())throw new IOException("已暂停，可点击继续下载");done+=n;if(done>expected)throw new IOException("下载大小与目录不一致");out.write(buffer,0,n);if(System.currentTimeMillis()-last>250){progress.update(done,expected);last=System.currentTimeMillis();}}out.getFD().sync();}if(done!=expected)throw new IOException("下载未完成，可点击继续下载");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(tmp)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(cancelled.getAsBoolean())throw new IOException("已暂停");digest.update(buffer,0,n);}}StringBuilder sha=new StringBuilder();for(byte n:digest.digest())sha.append(String.format(Locale.ROOT,"%02x",n&255));if(!sha.toString().equals(x.getString("sha256"))){tmp.delete();throw new IOException("文件校验失败，请重新下载");}if(!tmp.renameTo(target))throw new IOException("下载文件无法保存");progress.update(done,expected);return new JSONObject().put("cached",true);}finally{c.disconnect();}
 }
}
